<script setup lang="ts">import {ref} from'vue';import{FolderOpen,Plus,Sparkles}from'lucide-vue-next';const emit=defineEmits<{create:[name:string,path:string],open:[path:string]}>();const name=ref('我的空间'),path=ref('');</script>
<template><main class="home"><div class="brand"><span class="brandmark"><Sparkles/></span><h1>Infinite Canvas</h1><p>把任何东西拖进来，放到你想放的位置。</p></div><section class="home-card"><label>工作区名称<input v-model="name" placeholder="我的空间"></label><label>保存位置<input v-model="path" placeholder="例如 D:\InfiniteCanvas\MyProject"></label><button class="primary" @click="emit('create',name,path)"><Plus/>创建工作区</button><button @click="emit('open',path)"><FolderOpen/>打开工作区</button><small>工作区中的文件将被完整托管，移动整个文件夹即可迁移。</small></section></main></template>
